SINA_SMART["anat1-intro"] = {"lecture":"anat1-intro","title":"Introduction to anatomy","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-intro:e0","text":"Anatomy = morphology; anatome = cutting up = dissection.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e1","text":"Levels: chemical, cellular, tissue, organ, system, organism.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e2","text":"Gross (surface, regional, systemic), microscopic, developmental, pathological, radiographic anatomy.","topic":"Subdisciplines","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e3","text":"X-rays: air/fat radiotransparent; bone, stones, metals radiopaque; CT and MRI give sections.","topic":"Subdisciplines","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e4","text":"Terminologia Anatomica replaced Nomina Anatomica.","topic":"Subdisciplines","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e5","text":"Anatomical position: erect, palms forward, thumbs out.","topic":"Positions and directional terms","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e6","text":"Supine face up; prone face down; lateral recumbent on one side.","topic":"Positions and directional terms","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e7","text":"Proximal/distal only for limbs; hand axis 3rd finger, foot axis 2nd toe.","topic":"Positions and directional terms","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e10","text":"Elbow = hinge; pronation/supination at radio-ulnar joints.","topic":"Planes, axes and basic movements","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e8","text":"Planes: sagittal, frontal, transverse.","topic":"Planes, axes and basic movements","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-intro:e9","text":"Axes: left-right (flexion), anteroposterior (abduction), vertical (rotation).","topic":"Planes, axes and basic movements","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"fqojqs":"a","3d62kg":"a","1vnjc0l":"a","y59zrw":"a","p35zgj":"a","160yy6o":"a","k5j7fn":"a","10s1tnn":"a","10c1l3b":"a","1qeny6x":"a","1c0pqdq":"a","1ouq6xu":"a","12efw62":"a","19hxskz":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-intro:e0":{"s":0,"u":["Anatomy = morphology; anatome = cutting up = dissection.","Anatomy (Greek anatome , 'cutting up'; Latin equivalent: dissection ), also called morphology , is the study of the structure of the human body from the macroscopic to the microscopic level."],"dp":[]},"anat1-intro:e1":{"s":0,"u":["Levels: chemical, cellular, tissue, organ, system, organism.","Levels of organisation: chemical (atoms, macromolecules) → cellular → tissue (epithelial, connective, muscle, nervous) → organ (lung, liver, brain) → organ system → organism ."],"dp":[]},"anat1-intro:e2":{"s":1,"u":["Gross (surface, regional, systemic), microscopic, developmental, pathological, radiographic anatomy.","Gross anatomy : structures visible to the naked eye, studied by dissection ; includes surface anatomy (landmarks, abdominal quadrants), regional anatomy (the basis of surgery) and systemic anatomy (organs grouped by system).","Developmental anatomy (embryology) : how structures form, from fertilisation to adulthood."],"dp":[]},"anat1-intro:e3":{"s":1,"u":["X-rays: air/fat radiotransparent; bone, stones, metals radiopaque; CT and MRI give sections.","Radiographic anatomy : structure seen by imaging: X-rays pass easily through air and fat ( radiotransparent ) but are absorbed by bone, calcium stones and metals ( radiopaque ); CT rotates a narrow beam around the patient and a computer builds cross-sections; MRI uses electromagnetic energy for multiplanar sections."],"dp":[{"h":"Note","t":"Imaging: air and fat are radiolucent ; bone, calcium stones and metal are radiopaque . CT = X-ray slices; MRI = magnetic fields, best for soft tissue."}]},"anat1-intro:e4":{"s":1,"u":["Terminologia Anatomica replaced Nomina Anatomica.","The official vocabulary is the Terminologia Anatomica (which replaced the Nomina Anatomica); names come from objects (lunate, pisiform, scaphoid, mitral valve, coronary), geometric shapes (trapezius, pyramidalis, quadratus), colours (grey and white matter, yellow ligament)."],"dp":[]},"anat1-intro:e5":{"s":2,"u":["Anatomical position: erect, palms forward, thumbs out.","Anatomical position : standing erect, feet flat and toes forward, eyes forward, palms facing anteriorly with thumbs pointing away from the body ."],"dp":[{"h":"Why every description starts from the anatomical position","t":"A patient may be lying, sitting or twisted, and a forearm may be pronated or supinated. Describing everything as if the body stood in one agreed position, palms forward, removes ambiguity: 'the radius is lateral to the ulna' is then always true, whatever position the arm is actually in. Imaging also follows these conventions: an axial CT is viewed from below, with the patient's right on the viewer's left. Source: the lecture's anatomical position and planes slides."},{"h":"Note","t":"Anatomical position : standing, feet forward, palms facing forward, thumbs out . Every directional term assumes this position, whatever the patient is doing."}]},"anat1-intro:e6":{"s":2,"u":["Supine face up; prone face down; lateral recumbent on one side.","Clinical positions: supine (face up), prone (face down), right lateral recumbent (lying on the right side: access to the left side) and left lateral recumbent ."],"dp":[{"h":"Note","t":"Supine = face up; prone = face down. Pronation turns the palm backward; supination forward ('holding soup')."}]},"anat1-intro:e7":{"s":2,"u":["Proximal/distal only for limbs; hand axis 3rd finger, foot axis 2nd toe.","The hand's axis passes through the 3rd finger , the foot's through the 2nd toe .","Terms: superior (cranial) vs inferior (caudal) ; supra vs infra (supraspinatus above, infraspinatus below the scapular spine); medial (internal) vs lateral (external) ; anterior (ventral) vs posterior (dorsal) ('dorsal' also names the back of the hand and top of the foot); superficial vs deep ; proximal vs distal , reserved for the limbs (near or far from the limb root)."],"dp":[{"h":"Note","t":"Proximal/distal are used only for limbs ; on the trunk say superior/inferior. The hand's reference axis is the 3rd finger , the foot's the 2nd toe (for abduction/adduction of digits)."}]},"anat1-intro:e10":{"s":3,"u":["Elbow = hinge; pronation/supination at radio-ulnar joints.","Forearm: pronation (palm turns backward) and supination (palm forward) at the radio-ulnar joints.","Elbow : uniaxial hinge (flexion/extension only)."],"dp":[{"h":"Note","t":"Elbow = hinge (1 axis); shoulder = ball-and-socket (3 axes); pronation/supination happen at the radio-ulnar joints , not the elbow proper."}]},"anat1-intro:e8":{"s":3,"u":["Planes: sagittal, frontal, transverse.","Hip: flexion/extension in the sagittal plane (walking), abduction/adduction in the frontal plane.","Planes: sagittal (median = equal halves; parasagittal = unequal), frontal (coronal) : anterior/posterior, transverse (horizontal) : superior/inferior (axial CT/MRI slices)."],"dp":[{"h":"Note","t":"Planes : sagittal (median = equal halves), frontal/coronal, transverse (axial CT/MRI slices). Axes : left-right → flexion/extension; anteroposterior → abduction/adduction; vertical → rotation."}]},"anat1-intro:e9":{"s":3,"u":["Axes: left-right (flexion), anteroposterior (abduction), vertical (rotation).","Axes: left-right (flexion/extension, e.g. hip, knee), anteroposterior (abduction/adduction, e.g. shoulder), vertical (rotation, e.g. neck).","Shoulder (multiaxial ball-and-socket): flexion/extension, abduction/adduction, medial/lateral rotation."],"dp":[]}},"meta":{"fqojqs":{"a":"recall","vg":"anat1-intro:e0/recall/1"},"3d62kg":{"a":"recall","vg":"anat1-intro:e1/recall/1"},"1vnjc0l":{"a":"recall","vg":"anat1-intro:e2/recall/1"},"y59zrw":{"a":"recall","vg":"anat1-intro:e3/recall/1"},"p35zgj":{"a":"recall","vg":"anat1-intro:e4/recall/1"},"160yy6o":{"a":"recall","vg":"anat1-intro:e5/recall/1"},"k5j7fn":{"a":"application","vg":"anat1-intro:e6/application/1"},"10s1tnn":{"a":"recall","vg":"anat1-intro:e7/recall/1"},"10c1l3b":{"a":"recall","vg":"anat1-intro:e7/recall/2"},"1qeny6x":{"a":"recall","vg":"anat1-intro:e8/recall/1"},"1c0pqdq":{"a":"recall","vg":"anat1-intro:e8/recall/2"},"1ouq6xu":{"a":"recall","vg":"anat1-intro:e9/recall/1"},"12efw62":{"a":"recall","vg":"anat1-intro:e10/recall/1"},"19hxskz":{"a":"recall","vg":"anat1-intro:e10/recall/2"}},"explRev":"eae011b09879"};
